package space.manus.nacre.ime.input

import java.io.File
import java.io.FileInputStream
import java.io.InputStream
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Verifies that the bundled person_names.tsv is actually consumed through
 * the real loader path (NacreDictionary.load -> loadSupplementaryDict) and
 * that common Japanese person names surface as conversion candidates.
 *
 * The data file is generated by tools/dict/generate_person_names.py from
 * published national name rankings (see person_names_NOTES.md next to the
 * asset). Only generic, nationally common names are included.
 *
 * Runs on a plain JVM against the real bundled assets, with an empty
 * learning store and no KenLM scorer — same setup as ConversionBenchmarkTest.
 */
class PersonNamesDictTest {

    /** Serves asset names (e.g. "dict/person_names.tsv") from a directory on disk. */
    private class FileAssetOpener(private val root: File) : AssetOpener {
        override fun open(name: String): InputStream = FileInputStream(File(root, name))
    }

    /** Empty in-memory learning store: no user boost, no history, no phrases. */
    private class InMemoryStore : DictionaryKeyValueStore {
        private val strings = HashMap<String, String>()
        private val ints = HashMap<String, Int>()
        private val bools = HashMap<String, Boolean>()
        override fun getString(key: String): String? = strings[key]
        override fun putString(key: String, value: String) { strings[key] = value }
        override fun getInt(key: String, defaultValue: Int): Int = ints[key] ?: defaultValue
        override fun putInt(key: String, value: Int) { ints[key] = value }
        override fun getBoolean(key: String, defaultValue: Boolean): Boolean =
            bools[key] ?: defaultValue
    }

    /** Walk up from the test working directory until [relPath] exists. */
    private fun locateUpwards(relPath: String): File {
        var dir: File? = File(System.getProperty("user.dir")).absoluteFile
        while (dir != null) {
            val f = File(dir, relPath)
            if (f.exists()) return f
            dir = dir.parentFile
        }
        throw IllegalStateException("Could not locate $relPath upwards from ${System.getProperty("user.dir")}")
    }

    @Test
    fun personNamesAreLoadedAndConvert() {
        val assetsDir = try {
            locateUpwards("ime-core/src/main/assets")
        } catch (e: IllegalStateException) {
            locateUpwards("src/main/assets")
        }
        // The file under test must exist as a bundled asset.
        assertTrue(
            "dict/person_names.tsv must be bundled",
            File(assetsDir, "dict/person_names.tsv").isFile,
        )

        val stores = HashMap<String, InMemoryStore>()
        val dict = NacreDictionary(
            FileAssetOpener(assetsDir),
            { name -> stores.getOrPut(name) { InMemoryStore() } },
            null,
        )
        dict.load()
        assertTrue("dictionary must have loaded entries", dict.entryCount > 0)

        // reading -> expected surface, all generic nationally common names.
        val cases = listOf(
            // Full names (surname + given name as one entry)
            "さとうたろう" to "佐藤太郎",
            "たなかたろう" to "田中太郎",
            "たなかはなこ" to "田中花子",
            "すずきいちろう" to "鈴木一郎",
            "やまだはなこ" to "山田花子",
            "なかむらあきら" to "中村明",
            // Given-name kanji are ambiguous (健/剛/武/毅); any is a name.
            "わたなべたけし" to "渡辺健|渡辺剛|渡辺武|渡辺毅",
            "たかはしけん" to "高橋健|高橋建",
            "さいとうしょうた" to "斎藤翔太|斉藤翔太",
            // Surname alone
            "さいとう" to "斎藤",
            "はせがわ" to "長谷川",
            // Given name alone (classic and modern)
            "しょうた" to "翔太",
            "つむぎ" to "紬",
            "さとうりん" to "佐藤凛",
        )
        for ((reading, expected) in cases) {
            val candidates = dict.convert(reading)
            val accepted = expected.split('|')
            val rank = candidates.indexOfFirst { it.surface in accepted }
            println("person-name check: $reading -> $expected rank=${if (rank < 0) "absent" else rank + 1}")
            assertTrue(
                "$expected must be in the top 3 for $reading (top was ${candidates.firstOrNull()?.surface})",
                rank in 0..2,
            )
        }

        // A given name alone competes with ordinary words of the same
        // reading (はると: 春と / 貼ると), so the modern name only has to
        // be within the first five there.
        for ((reading, expected) in listOf("はると" to "陽翔")) {
            val rank = dict.convert(reading).indexOfFirst { it.surface == expected }
            assertTrue("$expected must be in the top 5 for $reading (rank ${rank + 1})", rank in 0..4)
        }

        // Single-character given names are inherently ambiguous alone
        // (りん: 林/倫/鈴/...), so presence is all we promise there; in a
        // full name (佐藤凛 above) they rank at the top.
        val presenceCases = listOf("りん" to "凛")
        for ((reading, expected) in presenceCases) {
            val candidates = dict.convert(reading)
            assertTrue(
                "$expected must be a candidate for $reading",
                candidates.any { it.surface == expected },
            )
        }

        // The canonical full names must rank first: converting a common
        // full name in one shot is the point of the composed entries.
        val top1Cases = listOf(
            "さとうたろう" to "佐藤太郎",
            "たなかたろう" to "田中太郎",
            "たなかはなこ" to "田中花子",
            "すずきいちろう" to "鈴木一郎",
            "やまだはなこ" to "山田花子",
            "なかむらあきら" to "中村明",
            "さいとう" to "斎藤",
            "はせがわ" to "長谷川",
            "しょうた" to "翔太",
        )
        for ((reading, expected) in top1Cases) {
            val top = dict.convert(reading).firstOrNull()?.surface
            assertTrue("$expected must rank first for $reading (was $top)", top == expected)
        }
    }
}
